$ErrorActionPreference = 'Stop'
$seed = 20261008
$rng = [System.Random]::new($seed)
$features = 'log_amount','amount_deviation_ratio','transaction_hour','time_of_day_deviation','transaction_count_30m','transaction_count_24h','beneficiary_age_days','beneficiary_risk_score','beneficiary_transaction_count','unique_beneficiary_count','is_new_beneficiary','device_age_days','is_new_device','recent_device_change','recent_account_recovery','recent_password_reset','recent_pin_reset','session_duration_deviation','interaction_velocity','navigation_deviation_score','session_anomaly_score','linked_risky_accounts','linked_risky_devices','linked_risky_beneficiaries','beneficiary_in_degree','beneficiary_out_degree','network_risk_score','account_age_days','average_daily_transactions'
$cats = @(@('normal',500,0),@('legitimate_high_value',100,0),@('borderline_unusual',100,0),@('new_beneficiary_abnormal_amount',70,1),@('new_device_high_value',60,1),@('rapid_transfers_new_beneficiary',60,1),@('risky_beneficiary_network',40,1),@('account_recovery_new_beneficiary',40,1),@('combined_high_risk',30,1))
$scenarios = [System.Collections.Generic.List[string]]::new()
foreach ($cat in $cats) { 1..([int]$cat[1]) | ForEach-Object { $scenarios.Add([string]$cat[0]) } }
for ($i=$scenarios.Count-1; $i -gt 0; $i--) { $j=$rng.Next($i+1); $tmp=$scenarios[$i]; $scenarios[$i]=$scenarios[$j]; $scenarios[$j]=$tmp }
$rows = foreach ($i in 0..999) {
  $scenario=$scenarios[$i]; $label=if($scenario -in @('new_beneficiary_abnormal_amount','new_device_high_value','rapid_transfers_new_beneficiary','risky_beneficiary_network','account_recovery_new_beneficiary','combined_high_risk')){1}else{0}; $high=$scenario -eq 'legitimate_high_value'
  $min=if($high){2000000}else{20000}; $max=if($high){8000000}else{250000}; $amount=[math]::Round($min+$rng.NextDouble()*($max-$min),2)
  $f=[ordered]@{}; foreach($name in $features){$f[$name]=0}
  $f.log_amount=[math]::Log(1+$amount); $f.amount_deviation_ratio=[math]::Round(.7+$rng.NextDouble()*.8,3); $f.transaction_hour=$rng.Next(24); $f.time_of_day_deviation=[math]::Round($rng.NextDouble(),3); $f.transaction_count_30m=$rng.Next(2); $f.transaction_count_24h=1+$rng.Next(5); $f.beneficiary_age_days=30+$rng.Next(1470); $f.beneficiary_risk_score=[math]::Round($rng.NextDouble()*15,2); $f.beneficiary_transaction_count=1+$rng.Next(50); $f.unique_beneficiary_count=1+$rng.Next(15); $f.device_age_days=30+$rng.Next(1470); $f.account_age_days=90+$rng.Next(2310); $f.session_duration_deviation=[math]::Round($rng.NextDouble()*.4,3); $f.interaction_velocity=[math]::Round($rng.NextDouble()*.4,3); $f.navigation_deviation_score=[math]::Round($rng.NextDouble()*.3,3); $f.session_anomaly_score=[math]::Round($rng.NextDouble()*.2,3); $f.average_daily_transactions=[math]::Round(.2+$rng.NextDouble()*7.8,2)
  if($scenario -in @('borderline_unusual','new_beneficiary_abnormal_amount')){$f.is_new_beneficiary=1;$f.beneficiary_age_days=0;$f.beneficiary_transaction_count=0;$f.amount_deviation_ratio=[math]::Round(2+$rng.NextDouble()*4,2);$f.session_anomaly_score=[math]::Round(.25+$rng.NextDouble()*.45,2)}
  if($scenario -in @('new_device_high_value','combined_high_risk')){$f.is_new_device=1;$f.device_age_days=0;$f.recent_device_change=1}
  if($scenario -eq 'rapid_transfers_new_beneficiary'){$f.is_new_beneficiary=1;$f.beneficiary_age_days=0;$f.transaction_count_30m=3+$rng.Next(4);$f.transaction_count_24h=5+$rng.Next(7)}
  if($scenario -eq 'risky_beneficiary_network'){$q=65+$rng.NextDouble()*25;$f.beneficiary_risk_score=$q;$f.network_risk_score=$q;$f.linked_risky_accounts=1;$f.linked_risky_beneficiaries=1}
  if($scenario -eq 'account_recovery_new_beneficiary'){$f.is_new_beneficiary=1;$f.beneficiary_age_days=0;$f.recent_account_recovery=1;$f.amount_deviation_ratio=[math]::Round(2.5+$rng.NextDouble()*2.5,2)}
  if($scenario -eq 'combined_high_risk'){$f.is_new_beneficiary=1;$f.beneficiary_age_days=0;$f.beneficiary_transaction_count=0;$f.recent_account_recovery=1;$f.beneficiary_risk_score=75;$f.network_risk_score=75;$f.linked_risky_accounts=1;$f.linked_risky_beneficiaries=1;$f.amount_deviation_ratio=[math]::Round(4+$rng.NextDouble()*4,2);$f.transaction_count_30m=3+$rng.Next(4);$f.transaction_count_24h=7+$rng.Next(6);$f.session_anomaly_score=[math]::Round(.65+$rng.NextDouble()*.3,2)}
  if($high){$f.amount_deviation_ratio=[math]::Round(.8+$rng.NextDouble()*.6,2);$f.beneficiary_risk_score=2;$f.session_anomaly_score=.05}
  $row=[ordered]@{transaction_id=('FRESH-{0}-{1:D4}' -f $seed,$i);account_id=('FACC-{0}-{1:D4}' -f $seed,$i);beneficiary_id=('FBEN-{0}-{1:D4}' -f $seed,$i);device_id=('FDEV-{0}-{1:D4}' -f $seed,$i);amount=$amount;currency='NGN';channel=@('mobile_app','web','ussd','api')[$rng.Next(4)];timestamp=[datetime]::new(2026,1,1,0,0,0,[DateTimeKind]::Utc).AddMinutes($i*11).ToString('o')}
  foreach($name in $features){$row[$name]=$f[$name]};$row.scenario_category=$scenario;$row.ground_truth_label=$label;[pscustomobject]$row
}
$out=Join-Path $PSScriptRoot '..\data\fresh_evaluation';New-Item -ItemType Directory -Force -Path $out|Out-Null
$rows|Export-Csv -NoTypeInformation -Encoding utf8 -Path (Join-Path $out 'fresh_synthetic_transactions.csv')
$counts=$cats|ForEach-Object{"| $($_[0]) | $($_[1]) |"}
$sample=$rows|Select-Object -First 12|ForEach-Object{"| $($_.transaction_id) | $($_.account_id) | $($_.amount) | $($_.channel) | $($_.scenario_category) | $($_.ground_truth_label) |"}
@("# TrustSentinel fresh synthetic evaluation data",'',"- Generated: 2026-10-08; seed: $seed; records: $($rows.Count).",'- Feature schema: trustsentinel-context-v1.','- Synthetic identifiers and values; generated independently of prior datasets.','- Not used for training or calibration; those scripts read only data/synthetic/transactions.csv.','- Feature columns are request context inputs grouped in the API context_features property. scenario_category and ground_truth_label are offline-only; exclude them from API/model input.','','| Category | Count |','|---|---:|') + $counts + @('','| transaction_id | account_id | amount | channel | scenario_category | ground_truth_label |','|---|---|---:|---|---|---:|') + $sample | Set-Content -Encoding utf8 (Join-Path $out 'fresh_synthetic_transactions.md')
Write-Output "Generated $($rows.Count) records using seed $seed."
